// Part "shell east (plots 4-7)": the walls, floors, partitions and gable infill of Cornell (4), Stanford (5),
// Winona (6) and Craftsman (7). Writes only into cells no earlier part has set (g.get undefined), and never into an
// opening: plan.md OPENINGS and the RESERVED stair holes, hearth mouths and flues stay air for later parts.
// Roofs, porches, fittings and chimneys are other parts; the gable triangles here are the wall's job (plan.md).

const key = (x, y, z) => `${x},${y},${z}`;
// inclusive range a..b
const R = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => a + i);

// add every cell of xs x ys x zs to the set of openings that stay air
function cut(holes, xs, ys, zs) {
  for (const x of xs) for (const y of ys) for (const z of zs) holes.add(key(x, y, z));
}

// write a block into air only: an opening, or a cell an earlier part has set, is left alone
function put(g, holes, x, y, z, block, state) {
  if (holes.has(key(x, y, z)) || g.get(x, y, z)) return;
  g.set(x, y, z, block, state);
}

// fill xs x ys x zs with one block (air-only, see put)
function fill(g, holes, xs, ys, zs, block, state) {
  for (const x of xs) for (const y of ys) for (const z of zs) put(g, holes, x, y, z, block, state);
}

// the outer ring of a house box x0..x1, z0..z1 at the rows ys: pick(x, y, z, corner) gives [block, state] or null
function ring(g, holes, { x0, x1, z0, z1, ys }, pick) {
  for (const y of ys) for (const x of R(x0, x1)) for (const z of R(z0, z1)) {
    if (!(x === x0 || x === x1 || z === z0 || z === z1)) continue;
    const corner = (x === x0 || x === x1) && (z === z0 || z === z1);
    const b = pick(x, y, z, corner);
    if (b) put(g, holes, x, y, z, b[0], b[1]);
  }
}

// a gable triangle on a face: fixed is the wall plane (z for a north/south face, x for an east/west one), a0..a1 the
// run of the wall, wallTop the top row of the wall. Each cell in from the edge rises one more row (45 degrees).
// A gable cell is laid only on something: the cell below it is wall or an earlier gable cell, so a window's head
// never leaves a floating or orphan block above it.
function gable(g, holes, { axis, fixed, a0, a1, wallTop, block }) {
  const at = (b, y) => (axis === "z" ? [b, y, fixed] : [fixed, y, b]);
  for (const b of R(a0, a1)) {
    const d = Math.min(b - a0, a1 - b);
    let below = true;
    for (let y = wallTop + 1; y <= wallTop + d; y++) {
      const [x, , z] = at(b, y);
      const [bx, , bz] = at(b, y - 1);
      const supported = below || g.get(bx, y - 1, bz);
      if (!supported || holes.has(key(x, y, z))) { below = false; continue; }
      put(g, holes, x, y, z, block);
      below = true;
    }
  }
}

// Cornell (plot 4): two-storey cube, x 67..77, z 13..21; interior x 68..76, z 14..20
function cornell(g) {
  const h = new Set();
  const FLOOR = "oak_planks", PART = "spruce_planks";
  // openings: north row (both floors; the door and sidelights share the ground row), west and east pairs, south pairs
  cut(h, [68, 69, 71, 72, 73, 75, 76], [2, 3, 6, 7], [13]);
  cut(h, [67], [2, 3, 6, 7], [14, 15, 19, 20]);
  cut(h, [77], [2, 3, 6, 7], [14, 15, 19, 20]);
  cut(h, [77], [1, 2], [17]);                       // hearth mouth (chimney() cuts it too)
  cut(h, [69, 70, 72, 74, 75], [2, 3], [21]);
  cut(h, [69, 70, 74, 75], [6, 7], [21]);
  cut(h, [68], [5], [15, 16, 17]);                  // stair hole, floor y5 (plan RESERVED)
  cut(h, [72], [2, 3, 6, 7], [18]);                 // hall doorway through the partition

  fill(g, h, R(68, 76), [1, 5], R(14, 20), FLOOR);
  ring(g, h, { x0: 67, x1: 77, z0: 13, z1: 21, ys: R(1, 8) }, (x, y, z, corner) => {
    if (y === 1) return ["bricks"];
    if (corner || y === 5) return ["smooth_quartz"];
    return ["cyan_terracotta"];
  });
  fill(g, h, R(69, 76), [2, 3, 4], [18], PART);     // partitions: living/parlour from dining/kitchen
  fill(g, h, R(69, 76), [6, 7, 8], [18], PART);
}

// Stanford (plot 5): one and a half storeys, x 83..93, z 14..21; interior x 84..92, z 15..20; side gables
function stanford(g) {
  const h = new Set();
  const FLOOR = "oak_planks", PART = "spruce_planks";
  cut(h, [84, 85, 88, 91, 92], [2, 3], [14]);       // north: pairs and the door
  cut(h, [83, 93], [2, 3], [15, 16]);               // side ground pairs
  cut(h, [83, 93], [7, 8], [17, 18]);               // gable pairs
  cut(h, [85, 86, 88, 90, 91], [2, 3], [21]);       // south: pairs and back door
  cut(h, [88], R(1, 6), [18]);                      // central flue and hearth mouth in the partition
  cut(h, [88], [1], [19]);                          // the hearth grate in the floor layer in front of the fire (grounds.mjs)
  cut(h, [92], [5], [17, 18, 19]);                  // stair hole (plan RESERVED)

  fill(g, h, R(84, 92), [1, 5], R(15, 20), FLOOR);
  ring(g, h, { x0: 83, x1: 93, z0: 14, z1: 21, ys: R(1, 6) }, (x, y, z, corner) => {
    if (y === 1) return ["bricks"];
    if (corner || y === 6) return ["smooth_quartz"];
    return ["calcite"];
  });
  gable(g, h, { axis: "x", fixed: 83, a0: 14, a1: 21, wallTop: 6, block: "calcite" });
  gable(g, h, { axis: "x", fixed: 93, a0: 14, a1: 21, wallTop: 6, block: "calcite" });
  fill(g, h, R(84, 91), [2, 3, 4, 6], [18], PART);  // partition with the central flue
}

// Winona (plot 6): one storey, front gable, x 100..108, z 13..22; interior x 101..107, z 14..21
function winona(g) {
  const h = new Set();
  const FLOOR = "oak_planks", PART = "spruce_planks";
  cut(h, [101, 102, 104, 106, 107], [2, 3], [13]);  // front pairs and door
  cut(h, [103, 104, 105], [6, 7], [13]);            // gable triple
  cut(h, [100, 108], [2, 3], [15, 16, 20, 21]);     // side pairs
  cut(h, [100], [1, 2], [18]);                      // hearth mouth (west wall, the chimney moved off the east side)
  cut(h, [102, 103, 106], [2, 3], [22]);            // back pair and back door
  cut(h, [105], [2, 3], [19]);                      // doorway through the partition

  fill(g, h, R(101, 107), [1], R(14, 21), FLOOR);
  ring(g, h, { x0: 100, x1: 108, z0: 13, z1: 22, ys: R(1, 4) }, (x, y, z, corner) => {
    if (y === 1) return ["cobblestone"];
    if (corner || y === 4) return ["smooth_quartz"];
    return ["smooth_sandstone"];
  });
  gable(g, h, { axis: "z", fixed: 13, a0: 100, a1: 108, wallTop: 4, block: "smooth_sandstone" });
  gable(g, h, { axis: "z", fixed: 22, a0: 100, a1: 108, wallTop: 4, block: "smooth_sandstone" });
  fill(g, h, R(101, 107), [2, 3, 4], [19], PART);   // partition: living and kitchen from the bedroom and bunk
}

// Craftsman (plot 7): two storeys, x 114..125, z 13..21; interior x 115..124, z 14..20; front and back gables
function craftsman(g) {
  const h = new Set();
  const FLOOR = "oak_planks", PART = "spruce_planks";
  cut(h, [115, 116, 117, 119, 122, 123], [2, 3], [13]);   // front ground: triple, door, pair
  cut(h, [115, 116, 122, 123], [6, 7], [13]);             // front upper pairs
  cut(h, [119, 120], [10, 11], [13]);                     // gable pair
  cut(h, [114], [2, 3, 6, 7], [14, 15, 19, 20]);          // west pairs
  cut(h, [125], [2, 3], [14, 15, 19, 20]);                // east ground pairs
  cut(h, [125], [6, 7], [19, 20]);                        // east upper beside the stack
  cut(h, [125], [1, 2], [17]);                            // hearth mouth
  cut(h, [116, 117, 121, 122], [2, 3, 6, 7], [21]);       // back pairs
  cut(h, [119], [2, 3], [21]);                            // back door
  cut(h, [115], [5], [15, 16, 17]);                       // stair hole (plan RESERVED)
  cut(h, [120], [2, 3, 4, 6, 7, 8], [18]);                // hall doorway through the partition

  fill(g, h, R(115, 124), [1, 5], R(14, 20), FLOOR);
  ring(g, h, { x0: 114, x1: 125, z0: 13, z1: 21, ys: R(1, 8) }, (x, y, z, corner) => {
    if (y === 1) return (x + z) % 4 === 0 ? ["mossy_cobblestone"] : ["cobblestone"];
    if (corner) return ["dark_oak_planks"];
    if (y <= 4) {
      const onNorthSouth = z === 13 || z === 21;
      return ["stripped_birch_log", { axis: onNorthSouth ? "x" : "z" }];
    }
    return ["spruce_planks"];
  });
  gable(g, h, { axis: "z", fixed: 13, a0: 114, a1: 125, wallTop: 8, block: "spruce_planks" });
  gable(g, h, { axis: "z", fixed: 21, a0: 114, a1: 125, wallTop: 8, block: "spruce_planks" });
  fill(g, h, R(116, 124), [2, 3, 4, 6, 7, 8], [18], PART); // partition: living from dining and kitchen
}

export function build(g) {
  cornell(g);
  stanford(g);
  winona(g);
  craftsman(g);
}
// Part "roofs": the eight roofs (plan.md ROOFS). Plot 0's hip is roof.json, laid by runParts right after the shell; the
// other seven are laid here by the roof tool, one per plot, with the chimney stacks and the other plots' wall tops kept.
import { roof, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { P2_SLABS, P3_SLABS } from "./shell-west.mjs";

// keep boxes as { from, to }: the chimney stacks (y0..20) and anything a part builds above the eave that must stay
const stack = (x0, z0, x1, z1) => ({ from: [x0, 0, z0], to: [x1, 20, z1] });

export function build(g) {
  // plot 0 Magnolia: low hip over the two storeys (plan ROOFS; the roof.json file was never written, so the plot had none).
  // The portico's pediment is the porch part's; the chimney stacks pass through the eaves, kept.
  roof(g, [2, 13, 13, 21], "hip", { texture: false, edges: { fascia: false }, soffit: "spruce",
    y: 9, pitch: 45, material: "deepslate_tiles", overhang: 1,
    // the chimney stacks, and the attic room's headroom (x5..10, y10..11, z15..19; rooms.json) with the ladder column x11 left
    // as air under the hip; the roof above y12 still carries the ridge
    keep: [stack(0, 16, 2, 18), stack(13, 16, 15, 18), { from: [5, 10, 15], to: [11, 11, 19] }],
  });

  // plot 0 Magnolia, after the hip: the attic keep box left the roof open along its front and back rows (y11, z15 and z19, x5..11):
  // close them with the hip's own stairs, then three small gabled dormers on the north slope (x3..5, x7..8, x10..12)
  for (let x = 5; x <= 11; x++) {
    g.set(x, 11, 15, ...B.stairs("deepslate_tile", "south"));
    g.set(x, 11, 19, ...B.stairs("deepslate_tile", "north"));
  }
  const wall = "white_concrete";
  for (const [x0, x1, cheeks] of [[3, 5, true], [7, 8, false], [10, 12, true]]) {
    const lo = cheeks ? x0 : x0 - 1, hi = cheeks ? x1 : x1 + 1;
    for (let x = lo; x <= hi; x++) {
      const pane = cheeks ? x > x0 && x < x1 : x >= x0 && x <= x1;
      for (const y of [10, 11]) {
        if (!cheeks && !pane && y === 10) continue;           // the middle dormer's cheeks stand on the roof stairs at y11 only
        if (pane) g.set(x, y, 14, "glass_pane", { east: "true", west: "true" }); else g.set(x, y, 14, wall);
      }
      if (x === lo) g.set(x, 12, 14, ...B.stairs("deepslate_tile", "east"));
      else if (x === hi) g.set(x, 12, 14, ...B.stairs("deepslate_tile", "west"));
      else g.set(x, 12, 14, "deepslate_tiles");
    }
    for (let x = x0; x <= x1; x++) if (x >= 4 && x <= 11) g.set(x, 12, 15, "deepslate_tiles");
  }

  // plot 1 Alhambra: front-gabled low roof behind the shaped parapet (ridge along z), red-tile, eaves on the sides only.
  // No fascia: the spruce trapdoors would hang off the corners of the eave with nothing behind them.
  roof(g, [18, 13, 29, 21], "gable", { texture: false, edges: { fascia: false }, soffit: "spruce",
    y: 9, ridgeAxis: "z", pitch: "half", material: "bricks", overhang: { north: 0, south: 1, east: 1, west: 1 },
    keep: [{ from: [18, 9, 13], to: [29, 14, 13] }, stack(26, 21, 28, 23)],
  });

  // plot 2 Vallonia: a LOW half-pitch side gable (1 up in 2) in dark shingle slabs, swept on down over the full-width porch at
  // the same pitch, with a wide shed dormer on the front slope (x36..44, face z13). The profile is shell-west's P2_SLABS.
  // The beam row y5 at z9 and the soffit over the porch (y5, z10..12) are laid here; the stack x33..34 z16..18 is left clear.
  for (let x = 34; x <= 46; x++) {
    for (const [zs, [y, type]] of Object.entries(P2_SLABS)) {
      const z = +zs;

      if ((z === 22 && (x === 34 || x === 46)) || (x === 34 && z >= 15 && z <= 19) || (x === 35 && z >= 16 && z <= 18)) continue;
      const dormer = x >= 36 && x <= 44 && (z === 13 || z === 14);
      if (dormer) { g.set(x, 9, z, "deepslate_tile_slab", { type: "bottom" }); continue; }
      g.set(x, y, z, "deepslate_tile_slab", { type });
      // the verge: a spruce plank under the outer slab of each end so the roof reads as framed
    }
  }
  g.fill([35, 5, 9], [45, 5, 9], "stripped_spruce_log", { axis: "x" });
  g.fill([35, 5, 10], [45, 5, 12], "spruce_planks");
  // exposed rafter ends: the beam row's trapdoors are the porch part's (rafterTails at z8)

  // plot 3 Puritan: a gambrel, ridge along x: a vertical lower slope (shell-west: slate y5..8 front cheeks and rear) breaking to a
  // shallow slab upper slope (P3_SLABS), the long shed dormer across the front (x53..59: its face and roof one course up)
  for (let x = 50; x <= 62; x++) for (const [zs, [y, type]] of Object.entries(P3_SLABS)) {
    const z = +zs;
    if ((x === 62 && z === 17) || (x === 50 && z >= 15 && z <= 19) || (x === 51 && z >= 16 && z <= 18)) continue;
    if (x >= 53 && x <= 59 && (z === 13 || z === 14)) { g.set(x, 10, z, "deepslate_tile_slab", { type: "bottom" }); continue; }
    g.set(x, y, z, "deepslate_tile_slab", { type });
  }
  // the slab edge of the lower slope: a drip course of upside-down slate stairs along the front cheeks' foot and the rear
  for (let x = 51; x <= 61; x++) if (x < 53 || x > 59) g.set(x, 5, 12, ...B.stairs("deepslate_tile", "south", "top"));
  for (let x = 51; x <= 61; x++) g.set(x, 5, 22, ...B.stairs("deepslate_tile", "north", "top"));

  // plot 4 Cornell: low hip, wide eaves, hipped dormer on the front, and the hip porch roof over the full-width porch
  // plain eave and soffit, no fascia (plan ROOFS); the wide eave's end would otherwise float past the plot
  roof(g, [67, 13, 77, 21], "hip", { texture: false, edges: { fascia: false }, soffit: "spruce",
    y: 9, pitch: 45, material: "deepslate_tiles", overhang: 1,
    dormers: { face: "north", style: "hip", count: 1, width: 5 },
    keep: [stack(77, 16, 79, 18)],
  });
  // the porch roof is a flat slab deck at y5 (z10..12, the frieze row z9 is the porch part's) instead of a 45 degree hip: the hip
  // climbed to y7 against the wall and hid the upper windows, so the house read as one storey. Overhang one cell each side.
  for (let x = 66; x <= 78; x++) for (let z = 8; z <= 12; z++) if (z !== 9 || x < 67 || x > 77) g.set(x, 5, z, "deepslate_tile_slab", { type: "bottom" });

  // plot 5 Stanford: steep side gable with two gabled dormers on the front
  roof(g, [83, 14, 93, 21], "cottage", { texture: false, fascia: "spruce", soffit: "spruce",
    y: 7, ridgeAxis: "x", pitch: 45, material: "deepslate_tiles", verge: "smooth_quartz", overhang: 1,
    dormers: { face: "north", count: 2, style: "gable", width: 3 },
    // the side gable walls (shell) already stand at x 83 and 93 up the rake: the roof leaves those cells to them
    keep: [stack(87, 17, 89, 19), { from: [83, 6, 14], to: [83, 9, 21] }, { from: [93, 6, 14], to: [93, 9, 21] }],
  });

  // plot 5 Stanford: two small gabled dormers (x85..87, x89..91) on the front slope, a 1x2 window each at x86 / x90 (y8..9)
  for (const cx of [86, 90]) {
    for (const x of [cx - 1, cx + 1]) for (const z of [15, 16]) for (const y of [8, 9]) g.set(x, y, z, "calcite");
    for (const y of [8, 9]) g.set(cx, y, 15, "glass_pane", { east: "true", west: "true" });
    for (const y of [8, 9]) for (const z of [15, 16]) if (!(y === 8 && z === 16)) g.set(cx, y, z, "air");
    for (const z of [15, 16]) {
      g.set(cx - 1, 10, z, ...B.stairs("deepslate_tile", "east"));
      g.set(cx + 1, 10, z, ...B.stairs("deepslate_tile", "west"));
      g.set(cx, 10, z, z === 15 ? "calcite" : "deepslate_tiles");
    }
  }

  // plot 6 Winona: front gable, ridge along z at x 104 (gable end to the street)
  roof(g, [100, 13, 108, 22], "gable", { texture: false, fascia: "spruce", soffit: "spruce",
    y: 5, ridgeAxis: "z", pitch: 45, material: "spruce_planks", verge: "birch_planks", overhang: 1,
    // the front and back gable triangles are the shell's sandstone infill: the roof leaves them to the walls
    keep: [stack(98, 17, 99, 19), { from: [100, 5, 17], to: [100, 9, 19] }, { from: [100, 5, 13], to: [108, 9, 13] }, { from: [100, 5, 22], to: [108, 9, 22] }],
  });

  // plot 7 Craftsman: front gable with wide eaves and a half pitch, dark slate; the porch roof is a shed low to the north
  // no fascia: its east end at x 128 would be outside the site (the build grows to 129) and float
  roof(g, [114, 13, 125, 21], "gable", { texture: false, edges: { fascia: false }, soffit: "spruce",
    y: 9, ridgeAxis: "z", pitch: "half", material: "deepslate_tiles", verge: "dark_oak_planks", overhang: 2,
    // the gable triangles at z 13 and z 21 are the shell's spruce_planks upper storey: the roof leaves them to the walls
    keep: [stack(125, 16, 127, 18), { from: [114, 9, 13], to: [125, 13, 13] }, { from: [114, 9, 21], to: [125, 13, 21] }],
  });
  roof(g, [114, 9, 125, 12], "shed", { texture: false, edges: { fascia: false }, soffit: "spruce",
    y: 5, pitch: "half", material: "deepslate_tiles", overhang: 1,
    keep: [{ from: [114, 5, 13], to: [125, 8, 13] }],
  });
}
Second review (v2), only these; everything else stays exactly as it is.
- Plot 7 Craftsman: it has no front door on the street side (the only door is at the back, 119,2,21). Give it a front door under the front porch, facing the street, on the slab-ramp way in from the front walk (half steps only, a level cell before the door, 2 wide).
- Plot 3 Puritan: the way to the door at 56,2,13 is 1 wide; make the walk and the entry 2 wide, level across. And the gambrel still doesn't read: on each side the lower slope must be nearly vertical (2-3 courses of steep stairs or wall) and then break to a shallow upper slope, so the roof shows the gambrel's knee from the street.
- Plot 4 Cornell: it still reads as one storey under the hip. Raise the walls a full storey: two full floors of wall, with the upper floor's windows under the eaves, then the low hip and its dormer on top; the front porch stays one storey.
- Plot 5 Stanford: the two front dormers read ragged (loose white quartz stair pieces). Make each a neat gabled dormer: two short walls, a window, a small gable roof in the main roof's material, nothing loose.

