7:// one glass pane in a wall line: connects east and west along a north or south wall, north and south along an east or
8:// west wall (the same states windowPair sets), and only into air
9:function pane(g, x, y, z, face = "north") {
10:  if (!g.isAir(x, y, z)) return 0;
11:  const ew = face === "east" || face === "west";
12:  const state = ew
13:    ? { east: "false", west: "false", north: "true", south: "true" }
14:    : { east: "true", west: "true", north: "false", south: "false" };
15:  g.set(x, y, z, "glass_pane", state);
16:  return 1;
17:}
